INSERT INTO public.skill_registry (slug, name, description, department, category, tags, quality_score, author, is_public, is_verified, source_repo, source_url, source_license)
SELECT v.slug, v.name, v.description, v.department, v.category, v.tags, v.quality_score, 'Nexus', true, true, 'addyosmani/agent-skills', 'https://github.com/addyosmani/agent-skills', 'MIT'
FROM (VALUES
('nexus-design-de-api-e-contratos','Design de API e Contratos de Interface','Projeta interfaces difíceis de usar errado: nomeia recursos, versiona contratos, define erros previsíveis e fronteiras entre módulos, tornando o caminho correto o mais fácil de seguir em REST, GraphQL ou props de componentes.','ti','knowledge',ARRAY['ti','api','rest','graphql','contrato','interface','arquitetura','backend'],93),
('nexus-teste-em-navegador-devtools','Teste em Navegador Real com DevTools','Valida comportamento em runtime real: inspeciona o DOM, captura erros de console, analisa requisições de rede e mede performance no navegador em vez de deduzir o resultado a partir do código estático.','ti','tools',ARRAY['ti','navegador','browser','devtools','teste','frontend','debug','console'],90),
('nexus-pipeline-ci-cd','Pipeline de CI/CD e Portões de Qualidade','Automatiza portões de qualidade no pipeline — lint, tipos, testes e build — aplicando o princípio shift-left para barrar o defeito o mais cedo possível e impedir que qualquer mudança chegue à produção sem verificação.','ti','workflows',ARRAY['ti','ci','cd','pipeline','deploy','automacao','devops','build'],94),
('nexus-simplificacao-de-codigo','Simplificação de Código sem Mudar Comportamento','Reduz complexidade preservando o comportamento exato: elimina indireção desnecessária, achata condicionais e nomeia intenções, validando cada mudança pelo critério de leitura por alguém que chega agora ao time.','ti','workflows',ARRAY['ti','refactor','simplificacao','legibilidade','qualidade','manutencao','codigo'],91),
('nexus-engenharia-de-contexto','Engenharia de Contexto para Agentes','Cura deliberadamente o que o agente enxerga: monta arquivos de regras, injeta apenas o contexto relevante à tarefa e poda histórico redundante, combatendo tanto a alucinação por falta quanto a perda de foco por excesso.','ti','knowledge',ARRAY['ti','contexto','agente','prompt','rag','janela','orquestracao'],93),
('nexus-depreciacao-e-migracao','Depreciação e Migração Segura','Trata código como passivo: define janela de depreciação, telemetria de uso residual, caminho de migração assistida e data de remoção, garantindo que nenhum consumidor seja desligado sem aviso e sem alternativa.','ti','workflows',ARRAY['ti','depreciacao','migracao','legado','sunset','versionamento','api'],89),
('nexus-adr-e-documentacao','ADRs e Documentação de Decisões','Registra o porquê, não só o quê: documenta contexto, restrições, alternativas descartadas e consequências de cada decisão arquitetural em ADRs curtos que orientam humanos e agentes no futuro.','ti','knowledge',ARRAY['ti','adr','documentacao','arquitetura','decisao','contexto','registro'],90),
('nexus-desenvolvimento-por-duvida','Desenvolvimento Orientado à Dúvida','Submete toda decisão não trivial a um revisor de contexto limpo, enviesado a refutar e não a aprovar, cruzando evidência ainda em voo — quando corrigir o rumo é barato — em vez de depurar depois.','ti','prompts',ARRAY['ti','duvida','revisao','adversarial','evidencia','qualidade','risco'],92),
('nexus-engenharia-de-ui-producao','Engenharia de UI de Nível Produção','Constrói interfaces acessíveis, responsivas e polidas com aderência real ao design system, foco em WCAG, estados de carregamento e erro, evitando a estética genérica de saída gerada por IA.','ti','knowledge',ARRAY['ti','ui','frontend','acessibilidade','wcag','design','responsivo','componente'],94),
('nexus-refinamento-de-ideias','Refinamento Divergente-Convergente de Ideias','Expande a ideia crua em variações, estressa premissas e só então converge para um conceito único acionável, com critério explícito de escolha e as opções descartadas registradas.','ti','prompts',ARRAY['ti','ideacao','brainstorm','divergente','convergente','produto','escopo'],88),
('nexus-implementacao-incremental','Implementação em Fatias Verticais','Entrega em fatias verticais finas: implementa uma parte, testa, verifica e só então expande, mantendo o sistema funcional e testável ao fim de cada incremento em vez de um único salto grande.','ti','workflows',ARRAY['ti','incremental','entrega','fatia','iteracao','plano','deploy'],92),
('nexus-entrevista-de-intencao','Entrevista de Intenção do Solicitante','Faz uma pergunta por vez até atingir alta confiança sobre a intenção real por trás do pedido, separando o que foi pedido do que resolve o problema, antes de existir plano, especificação ou código.','ti','prompts',ARRAY['ti','entrevista','requisitos','intencao','descoberta','escopo','produto'],91),
('nexus-observabilidade-instrumentacao','Observabilidade e Instrumentação','Instrumenta logs estruturados, métricas, tracing e alertas para que o comportamento em produção seja diagnosticável por evidência, respondendo o que o sistema está fazendo sem depender de reprodução local.','ti','tools',ARRAY['ti','observabilidade','logs','metricas','tracing','alerta','monitoramento','sre'],94),
('nexus-otimizacao-de-performance','Otimização de Performance Guiada por Medição','Proíbe otimizar por intuição: estabelece baseline, perfila o gargalo real, aplica uma mudança por vez e comprova o ganho com medição comparável, revertendo o que não se pagar.','ti','workflows',ARRAY['ti','performance','profiling','latencia','benchmark','otimizacao','medicao'],93),
('nexus-hardening-de-seguranca','Hardening de Segurança Aplicada','Revisa superfícies de ataque de forma sistemática: validação de entrada, autenticação e autorização por requisição, gestão de segredos, dependências e mensagens de erro que não vazam detalhes internos.','ti','knowledge',ARRAY['ti','seguranca','hardening','autorizacao','segredos','validacao','owasp','rls'],96),
('nexus-checklist-de-lancamento','Checklist de Lançamento e Rollout','Conduz o lançamento com rollout progressivo, feature flags, plano de rollback ensaiado, monitoramento pós-deploy e critérios objetivos de aborto definidos antes de publicar a mudança.','ti','workflows',ARRAY['ti','lancamento','rollout','flag','rollback','deploy','producao','monitoramento'],93),
('nexus-desenvolvimento-orientado-a-fonte','Desenvolvimento Orientado à Fonte Primária','Exige consulta à fonte primária — código da dependência, documentação oficial ou especificação — antes de afirmar comportamento de biblioteca, substituindo memória do modelo por evidência citável.','ti','workflows',ARRAY['ti','fonte','documentacao','dependencia','evidencia','pesquisa','biblioteca'],91),
('nexus-spec-driven-development','Desenvolvimento Orientado a Especificação','Escreve a especificação executável antes do código: comportamento esperado, casos de borda e critérios de aceite verificáveis, que passam a servir de contrato para implementação e revisão.','ti','workflows',ARRAY['ti','especificacao','spec','requisitos','aceite','contrato','qualidade'],92)
) AS v(slug,name,description,department,category,tags,quality_score)
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, department=EXCLUDED.department, category=EXCLUDED.category, tags=EXCLUDED.tags, quality_score=EXCLUDED.quality_score, source_repo=EXCLUDED.source_repo, source_url=EXCLUDED.source_url, source_license=EXCLUDED.source_license, updated_at=now();